example.code:
public class Main {
    public static void main(String[] args) {
        int left = 5, right = 9;
        System.out.println("Before");
        System.out.print("left = ");
        System.out.println(left);
        System.out.print("right = ");
        System.out.println(right);

        int temp = left;
        left = right;
        right = temp;

        System.out.println("After");
        System.out.print("left = ");
        System.out.println(left);
        System.out.print("right = ");
        System.out.println(right);
    }
}

